import React, { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";

function UploadArtifactPage() {
    const { studyId } = useParams();
    const navigate = useNavigate();

    const [userFiles, setUserFiles] = useState([]);
    const [showTagModal, setShowTagModal] = useState(false);
    const [selectedFile, setSelectedFile] = useState(null);
    const [category, setCategory] = useState("");
    const [categoryOption, setCategoryOption] = useState(""); // 🔹 NEW: subtype (Clone, Original, etc.)
    const [tags, setTags] = useState([]);
    const [tagInput, setTagInput] = useState("");
    const [showRenameModal, setShowRenameModal] = useState(false);
    const [fileToRename, setFileToRename] = useState(null);
    const [newFileName, setNewFileName] = useState("");

    // 🔹 Flags used in UI/logic
    const autoTagActive = !!categoryOption; // when subtype selected, tags are auto-managed
    const saveDisabled = category === "Code" && !categoryOption; // require subtype for Code

    useEffect(() => {
        const token = localStorage.getItem("token");
        if (!token) {
            navigate("/upload-artifact");
            return;
        }

        fetch(`http://localhost:8080/myFiles`, {
            credentials: "include",
            headers: {
                Authorization: `Bearer ${token}`,
            },
        })
            .then((res) => {
                if (res.status === 401 || res.status === 403) {
                    handleExpiredToken();
                    return [];
                }
                if (!res.ok) return [];
                return res.json();
            })
            .then((data) => {
                if (!Array.isArray(data)) data = [];
                setUserFiles(data);
            })
            .catch(() => setUserFiles([]));
    }, []);

    const handleExpiredToken = () => {
        alert("🔒 Your session has expired. Please login again.");
        localStorage.removeItem("token");
        localStorage.removeItem("user");
        navigate("/");
    };

    const handleFileUpload = async (e) => {
        const file = e.target.files[0];
        if (!file) return;

        const formData = new FormData();
        formData.append("file", file);

        try {
            const token = localStorage.getItem("token");
            if (!token) return handleExpiredToken();

            const res = await fetch(`http://localhost:8080/uploadFile`, {
                method: "POST",
                headers: { Authorization: `Bearer ${token}` },
                body: formData,
            });

            if (res.status === 401 || res.status === 403) return handleExpiredToken();

            const data = await res.json();
            if (res.ok) {
                alert(`✅ "${file.name}" uploaded successfully!`);
                const refresh = await fetch("http://localhost:8080/myFiles", {
                    headers: { Authorization: `Bearer ${token}` },
                });
                const newData = await refresh.json();
                setUserFiles(Array.isArray(newData) ? newData : []);
            } else {
                alert("❌ " + (data.error || "Upload failed"));
            }
        } catch (err) {
            console.error(err);
            alert("❌ Upload failed!");
        }
        e.target.value = "";
    };

    const handleDelete = async (fileId, fileName) => {
        if (!window.confirm(`Delete "${fileName}"?`)) return;
        try {
            const token = localStorage.getItem("token");
            if (!token) return handleExpiredToken();

            const res = await fetch(`http://localhost:8080/deleteFile/${fileId}`, {
                method: "DELETE",
                headers: { Authorization: `Bearer ${token}` },
            });

            if (res.status === 401 || res.status === 403) return handleExpiredToken();

            const data = await res.json();
            if (res.ok) {
                alert(`🗑️ ${data.message}`);
                setUserFiles((prev) => prev.filter((f) => f.id !== fileId));
            } else {
                alert("❌ " + data.error);
            }
        } catch {
            alert("❌ Delete failed!");
        }
    };

    // 🔹 Detect language tag from filename (for code artifacts)
    const detectLanguageTag = (filename) => {
        if (!filename) return null;
        const ext = filename.split(".").pop().toLowerCase();

        const map = {
            js: "javascript",
            jsx: "javascript",
            ts: "typescript",
            tsx: "typescript",
            py: "python",
            java: "java",
            cpp: "cpp",
            c: "c",
            rb: "ruby",
            go: "golang",
            rs: "rust",
            html: "html",
            css: "css",
            swift: "swift",
            md: "markdown",
        };

        return map[ext] || null;
    };

    // 🔹 Auto-generate tags when category + subtype selected
    useEffect(() => {
        if (!category || !categoryOption || !selectedFile) return;

        let baseTags = [];

        if (category === "Code") {
            baseTags = [categoryOption.toLowerCase()];
            const lang = detectLanguageTag(selectedFile.filename);
            if (lang) baseTags.push(lang);
        } else if (category === "Design / Diagram") {
            baseTags = [categoryOption.toLowerCase()];
        } else if (category === "Documentation") {
            baseTags = [categoryOption.toLowerCase()];
        }

        setTags([...new Set(baseTags)]);
    }, [category, categoryOption, selectedFile]);

    const openTagModal = (file) => {
        setSelectedFile(file);
        setCategory(file.category || "");
        setTags(file.tags ? file.tags.split(",") : []);
        setCategoryOption(""); // reset subtype when reopening
        setShowTagModal(true);
    };

    const closeTagModal = () => {
        setShowTagModal(false);
        setSelectedFile(null);
        setCategory("");
        setTags([]);
        setTagInput("");
        setCategoryOption("");
    };

    const handleAddTag = () => {
        if (autoTagActive) return; // 🔹 manual add disabled when auto-tags are active
        if (tagInput.trim() !== "" && !tags.includes(tagInput.trim())) {
            setTags([...tags, tagInput.trim()]);
            setTagInput("");
        }
    };

    const removeTag = (tagToRemove) => {
        setTags(tags.filter((t) => t !== tagToRemove));
    };

    const saveClassification = async () => {
        if (!selectedFile) return;

        // 🔹 Require subtype for Code before save
        if (category === "Code" && !categoryOption) {
            alert("⚠ Please select a subtype (Clone / Original) before saving code artifacts.");
            return;
        }

        try {
            const token = localStorage.getItem("token");
            if (!token) return handleExpiredToken();

            const res = await fetch(`http://localhost:8080/classifyFile/${selectedFile.id}`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify({ category, tags }),
            });

            if (res.status === 401 || res.status === 403) return handleExpiredToken();

            const data = await res.json();
            if (res.ok) {
                alert("✅ Classification saved!");
                setUserFiles((prev) =>
                    prev.map((f) =>
                        f.id === selectedFile.id
                            ? { ...f, category, tags: tags.join(",") }
                            : f
                    )
                );
                closeTagModal();
            } else alert("❌ " + data.error);
        } catch (err) {
            console.error(err);
            alert("❌ Save failed!");
        }
    };

    const getCategoryStyle = (cat) => {
        // 🔹 Map your "Design / Diagram" value to existing "Design" styling
        if (cat === "Design / Diagram") cat = "Design";

        const styles = {
            Design: { bg: "rgba(124,58,237,0.2)", color: "#c4b5fd", border: "rgba(124,58,237,0.5)" },
            Code: { bg: "rgba(96,165,250,0.2)", color: "#93c5fd", border: "rgba(96,165,250,0.5)" },
            Documentation: { bg: "rgba(16,185,129,0.2)", color: "#86efac", border: "rgba(16,185,129,0.5)" },
        };
        return styles[cat] || { bg: "rgba(107,114,128,0.2)", color: "#cbd5e1", border: "rgba(107,114,128,0.5)" };
    };

    return (
        <div style={styles.container}>
            {/* 🔹 PAGE HEADER */}
            <div style={styles.headerBar}>
                <h1 style={styles.title}>⬆️ Upload Artifacts</h1>

                <button
                    style={styles.backButton}
                    onClick={() => navigate(-1)}
                >
                    ← Back
                </button>
            </div>

            {/* 📤 Upload Section */}
            <div style={styles.uploadSection}>
                <input
                    type="file"
                    accept=".txt,.pdf,.png,.jpeg,.jpg,.json,.docx,.xlsx,.cpp,.java,.js,.py,.rb,.html,.css,.md,.csv,.swift,.ts,.go,.rs,.xml,.yml,.yaml"
                    onChange={handleFileUpload}
                    style={{ display: "none" }}
                    id="file-upload"
                />
                <label htmlFor="file-upload" style={styles.uploadBox}>
                    <p style={styles.uploadText}>
                        📁 Click to upload or drag and drop
                    </p>
                    <p style={styles.uploadSubtext}>
                        Supported formats: TXT, PDF, PNG, JPEG, JSON, DOCX, CSV (Max 50MB)
                    </p>
                </label>
            </div>

            {/* 📁 File List */}
            {userFiles.length > 0 && (
                <div style={styles.fileListContainer}>
                    <h3 style={styles.fileListTitle}>
                        Your Files ({userFiles.length})
                    </h3>
                    <div style={styles.list}>
                        {userFiles.map((file) => {
                            const catStyle = getCategoryStyle(file.category);
                            return (
                                <div key={file.id} style={styles.card}>
                                    <div style={styles.cardHeader}>
                                        <div>
                                            <h4 style={styles.filename}>{file.filename}</h4>
                                            <p style={styles.uploadDate}>
                                                {new Date(file.uploadDate).toLocaleString()}
                                            </p>
                                            <div style={styles.tagsContainer}>
                                                {file.category && (
                                                    <span
                                                        style={{
                                                            background: catStyle.bg,
                                                            color: catStyle.color,
                                                            border: `1px solid ${catStyle.border}`,
                                                            borderRadius: "8px",
                                                            padding: "4px 10px",
                                                            fontSize: "0.85rem",
                                                        }}
                                                    >
                                                        {file.category}
                                                    </span>
                                                )}
                                                {file.tags &&
                                                    file.tags.split(",").map((t, i) => (
                                                        <span key={i} style={styles.tag}>
                                                            #{t}
                                                        </span>
                                                    ))}
                                            </div>
                                        </div>

                                        <div style={styles.actionButtons}>
                                            <button
                                                onClick={() => openTagModal(file)}
                                                style={styles.tagButton}
                                            >
                                                🏷
                                            </button>
                                            <button
                                                onClick={() => handleDelete(file.id, file.filename)}
                                                style={styles.deleteButton}
                                            >
                                                🗑
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* 🏷 Modal */}
            {showTagModal && (
                <div style={styles.modalOverlay}>
                    <div style={styles.modal}>
                        <h2 style={styles.modalTitle}>🏷️ Artifact Classification</h2>

                        <label style={styles.label}>Category</label>
                        <select
                            value={category}
                            onChange={(e) => {
                                setCategory(e.target.value);
                                setCategoryOption("");
                                setTags([]);
                            }}
                            // 🔹 Prevent accidental misclassification for code: lock category when subtype chosen
                            disabled={category === "Code" && !!categoryOption}
                            style={{
                                ...styles.select,
                                opacity: category === "Code" && !!categoryOption ? 0.7 : 1,
                                cursor: category === "Code" && !!categoryOption ? "not-allowed" : "pointer",
                            }}
                        >
                            <option value="">Select category...</option>
                            <option value="Design / Diagram"> Design/Diagram</option>
                            <option value="Code"> Code</option>
                            <option value="Documentation"> Documentation</option>
                        </select>

                        {/* 🔹 Subtype options based on category */}
                        {category === "Code" && (
                            <div style={styles.optionRow}>
                                <button
                                    type="button"
                                    style={categoryOption === "Clone" ? styles.optionActive : styles.optionButton}
                                    onClick={() => setCategoryOption("Clone")}
                                >
                                    Clone
                                </button>
                                <button
                                    type="button"
                                    style={categoryOption === "Original" ? styles.optionActive : styles.optionButton}
                                    onClick={() => setCategoryOption("Original")}
                                >
                                    Original
                                </button>
                            </div>
                        )}

                        {category === "Design / Diagram" && (
                            <div style={styles.optionRow}>
                                {["Wireframe", "UML", "UI Mockup"].map((opt) => (
                                    <button
                                        key={opt}
                                        type="button"
                                        style={categoryOption === opt ? styles.optionActive : styles.optionButton}
                                        onClick={() => setCategoryOption(opt)}
                                    >
                                        {opt}
                                    </button>
                                ))}
                            </div>
                        )}

                        {category === "Documentation" && (
                            <div style={styles.optionRow}>
                                {["Report", "Manual", "Specification"].map((opt) => (
                                    <button
                                        key={opt}
                                        type="button"
                                        style={categoryOption === opt ? styles.optionActive : styles.optionButton}
                                        onClick={() => setCategoryOption(opt)}
                                    >
                                        {opt}
                                    </button>
                                ))}
                            </div>
                        )}

                        {category === "Code" && categoryOption && (
                            <p style={styles.categoryLockedInfo}>
                                Category is locked while a code subtype is selected. Close and reopen to change it.
                            </p>
                        )}

                        <label style={styles.label}>Tags</label>
                        <div style={styles.modalTagsContainer}>
                            {tags.map((t, i) => (
                                <span key={i} style={styles.modalTag}>
                                    #{t}
                                    <button
                                        onClick={() => removeTag(t)}
                                        style={styles.removeTagButton}
                                    >
                                        ×
                                    </button>
                                </span>
                            ))}
                        </div>

                        {/* 🔹 Manual tag input disabled when auto-tags are active */}
                        {!autoTagActive && (
                            <div style={styles.tagInputContainer}>
                                <input
                                    value={tagInput}
                                    onChange={(e) => setTagInput(e.target.value)}
                                    placeholder="Enter tag name..."
                                    onKeyPress={(e) => e.key === "Enter" && handleAddTag()}
                                    style={styles.input}
                                />
                                <button onClick={handleAddTag} style={styles.addTagButton}>
                                    Add
                                </button>
                            </div>
                        )}
                        {autoTagActive && (
                            <p style={styles.autoTagInfo}>
                                Tags are automatically generated from the selected type.
                            </p>
                        )}

                        <div style={styles.modalActions}>
                            <button
                                onClick={saveClassification}
                                style={{
                                    ...styles.saveButton,
                                    opacity: saveDisabled ? 0.6 : 1,
                                    cursor: saveDisabled ? "not-allowed" : "pointer",
                                }}
                                disabled={saveDisabled}
                            >
                                💾 Save
                            </button>
                            <button onClick={closeTagModal} style={styles.cancelButton}>
                                Cancel
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

const styles = {
    container: {
        minHeight: "100vh",
        background: "linear-gradient(135deg, #0f172a, #1e293b)",
