        maxWidth: "800px",
        margin: "0 auto 40px",
    },

    uploadBox: {
        display: "block",
        textAlign: "center",
        padding: "60px 20px",
        border: "2px dashed rgba(56,189,248,0.4)",
        borderRadius: "12px",
        cursor: "pointer",
        background: "rgba(255,255,255,0.02)",
        transition: "all 0.3s ease",
    },

    uploadText: {
        fontSize: "1.1rem",
        fontWeight: "600",
        color: "#38bdf8",
        margin: "0 0 8px 0",
    },

    uploadSubtext: {
        fontSize: "0.9rem",
        color: "#94a3b8",
        margin: 0,
    },

    fileListContainer: {
        maxWidth: "800px",
        margin: "0 auto",
    },

    fileListTitle: {
        fontSize: "1.3rem",
        fontWeight: "600",
        color: "#f8fafc",
        marginBottom: "20px",
    },

    list: {
        display: "flex",
        flexDirection: "column",
        gap: "16px",
    },

    card: {
        background: "rgba(255,255,255,0.05)",
        border: "1px solid rgba(255,255,255,0.1)",
        borderRadius: "12px",
        padding: "20px",
        boxShadow: "0 0 8px rgba(59,130,246,0.25)",
        transition: "all 0.3s ease",
    },

    cardHeader: {
        display: "flex",
        justifyContent: "space-between",
        alignItems: "flex-start",
    },

    filename: {
        fontSize: "1.1rem",
        fontWeight: "600",
        color: "#f8fafc",
        margin: "0 0 6px 0",
    },

    uploadDate: {
        fontSize: "0.85rem",
        color: "#94a3b8",
        margin: "0 0 10px 0",
    },

